// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address sender, uint256 amount, bytes calldata data) public {
        vm.assume(sender != address(0));
        vm.assume(sender != c.owner());
        vm.assume(amount > 0);
        vm.deal(c.owner(), amount);
        vm.prank(c.owner());
        (bool ok,) = address(c).call{value: amount}("");
        require(ok);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        (bool sentOk,) = address(c).call{value: 0}(
            abi.encodeWithSelector(SimpleWallet.sendMoney.selector, sender, amount, data)
        );
        assertFalse(sentOk, "non-owner sendMoney should revert");
    }
}
